def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the horizontal three-color seed.
    seed = None
    for r in range(h):
        for c in range(w - 2):
            if all(grid[r][c + k] != 0 for k in range(3)):
                seed = (r, c)
                break
        if seed:
            break
    if seed is None:
        return out

    r0, c0 = seed
    left, middle, right = grid[r0][c0:c0 + 3]

    # The middle color is a vertical ray through the grid.
    for r in range(h):
        out[r][c0 + 1] = middle

    # Each outer seed color connects to its isolated matching marker using
    # an L-shaped path: first along its seed column, then along marker row.
    for color, seed_col in ((left, c0), (right, c0 + 2)):
        markers = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color and not
                   (r == r0 and c0 <= c <= c0 + 2)]
        if not markers:
            continue
        r, c = markers[0]
        for rr in range(min(r0, r), max(r0, r) + 1):
            out[rr][seed_col] = color
        for cc in range(min(seed_col, c), max(seed_col, c) + 1):
            out[r][cc] = color
    return out
